class PythonQtThreadStateSaver
{
  Q_DISABLE_COPY(PythonQtThreadStateSaver)
public:
  PythonQtThreadStateSaver() { save(); }

  ~PythonQtThreadStateSaver() { restore(); }

  void save() { _state = PyEval_SaveThread(); }

  void restore()
