554: void PythonQtPrivate::registerClass(const QMetaObject* metaobject, const char* package,
555:   PythonQtQObjectCreatorFunctionCB* wrapperCreator, PythonQtShellSetInstanceWrapperCB* shell, PyObject* module,
556:   int typeSlots)
557: {
558:   // we register all classes in the hierarchy
559:   const QMetaObject* m = metaobject;
560:   bool first = true;
561:   while (m) {
562:     PythonQtClassInfo* info = lookupClassInfoAndCreateIfNotPresent(m->className());
563:     if (!info->pythonQtClassWrapper()) {
564:       info->setTypeSlots(typeSlots);
565:       info->setupQObject(m);
566:       createPythonQtClassWrapper(info, package, module);
567:       if (m->superClass()) {
568:         PythonQtClassInfo* parentInfo = lookupClassInfoAndCreateIfNotPresent(m->superClass()->className());
569:         info->addParentClass(PythonQtClassInfo::ParentClassInfo(parentInfo));
570:       }
571:     } else if (first && (module || (package && package[0]))) {
572:       // There is a wrapper already, but if we got a module, we want to place the wrapper into that module as well,
573:       // since it might have been placed into "private" earlier on.
574:       // If the wrapper was already added to module before, it is just readded, which does no harm.
575:       PyObject* classWrapper = info->pythonQtClassWrapper();
576:       // AddObject steals a reference, so we need to INCREF
577:       Py_INCREF(classWrapper);
578:       PyObject* pack = module ? module : packageByName(package); // same logic like in createPythonQtClassWrapper
579:       if (PyModule_AddObject(pack, info->className(), classWrapper) < 0) {
580:         Py_DECREF(classWrapper);
581:       }
582:     }
583:     if (first) {
584:       first = false;
585:       if (wrapperCreator) {
